-- 20260529_planning_district_demographics.sql
--
-- Restores per-Planning-District demographics (population, area, gross density,
-- wards, villages) for all 42 PDs from the RMP 2031 Volume-4 PDR.
-- Backs the District Intelligence panel at /admin/planning-intelligence and
-- the DealPlanningContextCard on every Bengaluru deal's Zoning tab.
--
-- Idempotent — re-runs delete any prior "rich" PD aggregate facts (those with
-- a populated `notes` field on their entries) and re-insert a fresh one. Thin
-- routing-key facts (entries without notes) are preserved so the dual-fact
-- read path in masterplan.service.js → getDistrictIntelligence() keeps working.
--
-- Source: extracted via scripts/extract-volume-4-pdr.py (Gemini multimodal on
-- 372 text-extractable pages of the 376-page PDR, 727K chars input → 14KB
-- JSON output, single API call, ~$0.03 spend). Notes-string format mirrors
-- the parseDistrictNotes() regex in masterplan.service.js — change one,
-- change the other.
--
-- Apply via:
--   Supabase SQL editor (paste this file's contents) — preferred
--   OR psql "$DATABASE_URL" -f database/migrations/20260529_planning_district_demographics.sql

BEGIN;

-- Idempotency: remove any previously-seeded rich PD fact (the one with notes)
-- before inserting the fresh extract. Thin routing-key facts (no notes)
-- stay so they can serve as the fallback if a future re-run partially fails.
DELETE FROM regulatory_data.evidence_facts
WHERE fact_type = 'rmp_table'
  AND fact_key = 'planning_districts'
  AND jsonb_typeof(fact_value) = 'array'
  AND jsonb_array_length(fact_value) > 10
  AND EXISTS (
    SELECT 1
    FROM jsonb_array_elements(fact_value) AS elem
    WHERE COALESCE(elem->>'notes', '') <> ''
  );

