-- Verification: should print 42 + however many thin routing-key facts existed.
-- The richest one (the one with notes on its entries) is what
-- getDistrictIntelligence() consumes.
SELECT
  COUNT(*) FILTER (
    WHERE fact_type = 'rmp_table' AND fact_key = 'planning_districts'
  )::int AS total_pd_facts,
  COUNT(*) FILTER (
    WHERE fact_type = 'rmp_table'
      AND fact_key = 'planning_districts'
      AND jsonb_array_length(fact_value) >= 42
  )::int AS rich_pd_facts
FROM regulatory_data.evidence_facts;

COMMIT;
